import { eligible } from "./eligibility.mjs";

// Realistic boundary: age derived from date of birth, then a caller that
// treats any error as "not eligible" (the common defensive pattern).
const MS_PER_YEAR = 365.25 * 24 * 60 * 60 * 1000;
const asOf = Date.parse("2026-10-12T00:00:00Z");
const ageFromDob = (dob) => (asOf - Date.parse(dob)) / MS_PER_YEAR;

function decide(age) {
  try { return eligible(age) ? "APPROVED" : "rejected (under 18)"; }
  catch { return "REJECTED (invalid age)"; }
}

for (const dob of ["1990-03-04", "2005-01-20", "2008-10-12", "2008-10-13", "1960-07-01"]) {
  const a = ageFromDob(dob);
  console.log(`dob=${dob}  age=${a.toFixed(4)}  ->  ${decide(a)}`);
}
