for (const dob of ["1990-03-04", "2005-01-20", "2008-10-12", "1960-07-01"]) {
  const a = Math.floor(ageFromDob(dob));
  console.log(`dob=${dob}  age=${a}  ->  ${decide(a)}`);
}
